C8 = [
("s2","Welke drie soorten versterkende elementen behandelt dit hoofdstuk?","De veldeffect-transistor (FET), de elektronenbuis en de (bipolaire) transistor."),
("s2","Wat is het verschil in soort versterking tussen FET/buis en transistor?","FET en buis zijn spanningsversterkers (met stroom als tussenstap). Een bipolaire transistor is een stroomversterker die als spanningsversterker kan worden geschakeld."),
("s2","Welke twee rollen hebben weerstanden bij versterkende elementen?","Het instellen van het element en het omzetten van een signaal in de vorm van stroom naar spanning."),
("s4","Hoe is een junctie-FET opgebouwd?","Met één PN-junctie die moet sperren. Het kanaal (N of P) voert de stroom, het andere deel is de gate. Het kanaal heeft twee aansluitingen: source en drain."),
("s4","Wat zijn de drie aansluitingen van een FET?","Gate (stuurelektrode), source (hier komen de ladingdragers binnen) en drain (hier gaan ze naar buiten)."),
("s4","Welke ladingdragers hoort bij een N-kanaal FET en bij een P-kanaal FET?","N-kanaal: elektronen. P-kanaal: gaten."),
("s4","Waarom loopt er geen (noemenswaardige) stroom door de gate van een junctie-FET?","De PN-junctie tussen gate en kanaal staat in sperrichting; in de uitputtingszone zijn geen vrije ladingdragers."),
("s4","Wat gebeurt er met de uitputtingszone als de gatespanning negatiever wordt (N-FET)?","De zone wordt breder, het geleidende deel van het kanaal smaller en de stroom kleiner."),
("s4","Wat is het afknijppunt (pinch-off)?","De gatespanning waarbij het hele kanaal uitputtingszone is. Dan stopt de stroom."),
("s4","Wat is de polariteit van een P-kanaal FET ten opzichte van een N-kanaal FET?","Tegengesteld: drain negatief ten opzichte van de source, gate 0 V of positief."),
("s4","Hoe zie je in het schemasymbool of een FET een N- of P-kanaal is?","Aan de richting van de pijl van de gate."),
("s4","Waarom neemt de uitputtingszone van source naar drain toe?","Het potentiaalverschil in het kanaal loopt op van source naar drain, dus de zone wordt breder en het geleidende deel smaller. Dat beperkt de invloed van de drainspanning op de stroom."),
("s5","Wat is de steilheid S van een FET?","De verandering van de drainstroom gedeeld door de verandering van de gatespanning die die verandering veroorzaakt: S = ΔI_D / ΔU_GS. Meestal in mA/V."),
("s5","Wat betekent S = 2 mA/V?","De drainstroom verandert 2 mA bij een verandering van de gatespanning met 1 V."),
("s5","Wat is het verband tussen steilheid en weerstand?","Steilheid is het omgekeerde van een weerstand: R = 1/S. Het is geen gewone weerstand, want de sturende spanning zit niet in de stroomkring zelf."),
("s5","Is de steilheid van een FET één vaste waarde?","Nee. De grafiek is krom, dus S is voor elk punt anders (bij kleinere stroom is S kleiner)."),
("s5","Hoe bepaal je de steilheid uit de ID/UGS-grafiek?","Neem een klein stuk om het punt, lees de stroom bij twee gatespanningen af en deel het stroomverschil door het spanningsverschil."),
("s5","Een FET heeft S = 4 mA/V. Welke weerstand hoort daarbij?","1/S = 1 / 4 mA/V = 250 Ω."),
("s6","Wat laat de ID/UDS-karakteristiek zien?","De drainstroom als functie van de spanning tussen drain en source, voor verschillende gatespanningen."),
("s6","Wat is het kenmerk van het vlakke deel van de ID/UDS-karakteristiek?","De drainstroom neemt daar nauwelijks nog toe met UDS: de FET gedraagt zich als een bron met hoge inwendige weerstand (aan de drainkant)."),
("s6","Wat is de kniespanning?","De drainspanning waarbij het steile deel overgaat in het vlakke deel van de ID/UDS-grafiek. Bij een FET is dat meer een knietraject, bij transistoren is de overgang scherper."),
("s6","Hoe bepaal je de inwendige weerstand Ri van een FET?","In het vlakke deel: ΔU_DS gedeeld door ΔI_D. Voorbeeld: 10 V / 0,55 mA ≈ 18 kΩ."),
("s6","Hoe groot is Ri ongeveer vergeleken met 1/S?","Veel groter, bij het voorbeeld ruwweg een factor 70 (18 kΩ tegen 250 Ω)."),
("s6","Is een FET aan de source laag- of hoogohmig, en aan de drain?","Aan de source laagohmig (weerstand 1/S), aan de drain hoogohmig (weerstand Ri)."),
("s8","Waarom kan omzetting van laagohmig naar hoogohmig versterking betekenen?","Dezelfde stroom loopt door 1/S (klein) en door R_D (groot). De spanning over de grote weerstand is evenveel keer groter als de weerstand."),
("s8","Formule voor de spanningsversterking van een FET zonder sourceweerstand?","Au = R_D / (1/S) = R_D · S."),
("s8","Een FET heeft S = 5 mA/V en R_D = 2 kΩ, zonder sourceweerstand. Hoe groot is Au?","Au = R_D · S = 2000 Ω · 0,005 A/V = 10."),
("s8","Wat is Au en waar staat de ‘u’ voor?","De spanningsversterking (A van amplification, u van signaalspanning): Au = U_uit / U_in."),
("s9","Hoe krijg je een negatieve gatespanning zonder negatieve bron?","Met een weerstand R_S in de sourceleiding. De stroom maakt de source positief ten opzichte van 0 V; de gate ligt via R_G aan 0 V, dus de gate is negatief ten opzichte van de source."),
("s9","Wat is het nadeel van een sourceweerstand?","De effectieve steilheid en dus de spanningsversterking worden kleiner: 1/S wordt R_S + 1/S."),
("s9","Formule voor de spanningsversterking met sourceweerstand?","Au = R_D / (R_S + 1/S), bij benadering Au ≈ R_D / R_S (iets kleiner)."),
("s9","Wat is de effectieve steilheid S′ bij een sourceweerstand?","S′ = 1 / (R_S + 1/S) = S / (S·R_S + 1)."),
("s9","Een FET met S = 4 mA/V krijgt R_S = 1 kΩ. Hoe groot wordt S′ en wat gebeurt er met Au?","S′ = 4 / 5 = 0,8 mA/V. Au wordt 5 keer zo klein."),
("s9","Welk voordeel heeft een sourceweerstand naast de negatieve gatespanning?","De steilheidsgrafiek wordt rechter, dus er is minder vervorming van het versterkte signaal."),
("s10","Welke drie basisschakelingen heeft een FET?","GSS (gemeenschappelijke source), GGS (gemeenschappelijke gate) en GDS (gemeenschappelijke drain, sourcevolger)."),
("s10","Waarom is de gate geen signaaluitgang en de drain geen signaalingang?","De gate heeft een extreem hoge weerstand. De drain kan door de hoge Ri de stroom in de FET niet noemenswaardig beïnvloeden."),
("s11","Wat zijn ingang en uitgang van de GSS?","Ingang: gate. Uitgang: drain. De source is gemeenschappelijk."),
("s11","Welke eigenschappen heeft de GSS?","Ingangsweerstand zeer hoog, spanningsversterking iets minder dan R_D/R_S, stroomversterking zeer groot, vermogensversterking zeer groot, in- en uitgang in tegenfase."),
("s11","Waarom zijn in- en uitgangssignaal bij de GSS in tegenfase?","Hogere gatespanning geeft meer stroom, dus meer spanning over R_D en daardoor een lagere drainspanning."),
("s12","Wat zijn ingang en uitgang van de GGS?","Ingang: source. Uitgang: drain. De gate is gemeenschappelijk (voor wisselspanning ontkoppeld)."),
("s12","Welke eigenschappen heeft de GGS?","Ingangsweerstand laag, spanningsversterking iets minder dan R_D/R_S, stroomversterking 1, vermogensversterking iets minder dan R_D/R_S, in- en uitgang in fase."),
("s12","Waarom is de stroomversterking van de GGS gelijk aan 1?","De signaalstroom loopt door de source én door het kanaal naar de drain: ingangsstroom en uitgangsstroom zijn gelijk."),
("s13","Wat zijn ingang en uitgang van de GDS (sourcevolger)?","Ingang: gate. Uitgang: source. De drain is gemeenschappelijk en heeft geen drainweerstand nodig."),
("s13","Welke eigenschappen heeft de GDS?","Ingangsweerstand zeer hoog, uitgangsweerstand laag, spanningsversterking iets kleiner dan 1, stroomversterking zeer groot, in fase."),
("s13","Waarvoor gebruik je een sourcevolger?","Om een signaal uit een hoogohmige bron met zo weinig mogelijk spanningsverlies naar een laagohmige belasting over te brengen."),
("s13","Waarom is de spanningsversterking van een sourcevolger iets kleiner dan 1?","1/S en R_S vormen een spanningsdeler; de uitgangsspanning staat over R_S."),
("s14","Welke basisschakeling heeft stroomversterking 1 en in fase?","De GGS (gemeenschappelijke gateschakeling)."),
("s14","Welke basisschakeling heeft spanningsversterking iets kleiner dan 1?","De GDS (sourcevolger)."),
("s14","Welke FET-schakeling keert de fase om?","De GSS: in- en uitgang in tegenfase."),
("s14","Welke basisschakeling heeft een zeer hoge ingangsweerstand en tegenfase?","De GSS."),
("s14","Welke basisschakeling heeft een lage ingangsweerstand?","De GGS (de ingang zit op de laagohmige source)."),
("s15","Waar staat MOSFET voor?","Metal Oxide Semiconductor Field Effect Transistor: een gate van metaal op een laagje oxide op halfgeleider."),
("s15","Wat is het verschil in gate tussen een MOSFET en een junctie-FET?","Bij een MOSFET is de gate door een oxidelaag geïsoleerd; er is nooit geleiding tussen gate en kanaal. De gateweerstand is 100 tot 1000 keer zo hoog."),
("s15","Waarom moet je voorzichtig zijn met MOSFET’s?","De dunne oxidelaag is gevoelig voor statische spanning. Gebruik een geaarde soldeerbout en eventueel een geaard polsbandje."),
("s15","Wat is het verschil tussen verrijkings- en uitputtingstype?","Een verrijkingstype geleidt pas als de gate een zekere spanning heeft. De FET’s van de junctie-soort zijn van het uitputtingstype."),
("s15","Wat is een dual-gate MOSFET?","Een MOSFET met twee gates. Gate 1 is de stuurelektrode. Gate 2 (tussen gate 1 en drain) krijgt een constante spanning en is voor HF ontkoppeld."),
("s15","Wat is het effect van de tweede gate van een dual-gate MOSFET?","De inwendige weerstand en dus de mogelijke versterking nemen toe. De capaciteit tussen gate 1 en drain wordt veel kleiner (enkele honderdsten van een pF), wat in HF-schakelingen van belang is."),
("s15","Is de capaciteit gate-source van een MOSFET groter of kleiner dan van een junctie-FET?","Ongeveer 10 keer kleiner."),
("s17","Waarom zijn elektronenbuizen de oudste versterkende elementen?","Ze zijn gebaseerd op elektronen in vacuüm en werden al in het begin van de 20e eeuw gebruikt."),
("s17","Welke ladingdragers hebben elektronenbuizen?","Alleen elektronen, nooit gaten."),
("s17","Welke buizen moet je voor het examen kennen?","De triode (één rooster) en de penthode (drie roosters)."),
("s17","Waar worden buizen nog gebruikt?","Vooral in audioversterkers van het duurdere segment en in HF-vermogenstoepassingen (eindtrappen van zenders)."),
("s18","Wat is thermische emissie?","Elektronen worden uit een hete geleider geslingerd. In vacuüm vormt zich een elektronenwolk rond de geleider."),
("s18","Waarom werkt thermische emissie alleen in vacuüm?","In lucht botsen de elektronen tegen luchtmoleculen en worden ze teruggetrokken. In vacuüm kunnen ze vrij naar de anode."),
("s19","Wat zijn de elektroden van een vacuümdiode?","Een kathode (verhit, zendt elektronen uit) en een anode (metalen plaat, positief)."),
("s19","Welke richting heeft de stroom in een buisdiode?","Alleen van anode naar kathode (technische stroomrichting); elektronen gaan van kathode naar anode. In de andere richting sperrend."),
("s19","Wat is het verschil tussen een direct en een indirect verhitte kathode?","Direct: de gloeidraad is zelf de kathode. Indirect: de kathode is een apart metalen buisje met een gloeidraad erin, meestal met wisselstroom gevoed."),
("s19","Waarom moet een buizenapparaat opwarmen?","Zolang de kathode te koud is, wordt er geen elektronenstroom uitgezonden."),
("s19","Waarom is de kathode bedekt met bariumoxide?","Dat materiaal laat gemakkelijk elektronen los."),
("s20","Wat is een triode?","Een buis met kathode, anode en één rooster ertussen. Het rooster heeft dezelfde functie als de gate van een FET."),
("s20","Hoe werkt het rooster van een triode?","Een negatieve roosterspanning ten opzichte van de kathode vermindert de elektronenstroom naar de anode; de roosterspanning stuurt de anodestroom."),
("s20","Welke namen hebben de drie basisschakelingen bij een triode?","Gemeenschappelijke kathodeschakeling (GKS, als GSS), gemeenschappelijke roosterschakeling (GRS, als GGS) en gemeenschappelijke anodeschakeling (GAS, kathodevolger, als GDS)."),
("s20","Wat is een kathodevolger?","Een triode in gemeenschappelijke anodeschakeling: ingang op het rooster, uitgang op de kathode. Spanningsversterking iets kleiner dan 1."),
("s20","Wat is bij een buis de steilheid S?","De verandering van de anodestroom gedeeld door de verandering van de roosterspanning, net als bij de FET (mA/V)."),
("s20","Welke FET-elektrode komt overeen met kathode, rooster en anode?","Source ↔ kathode, gate ↔ rooster, drain ↔ anode."),
("s21","Wat is een tetrode?","Een buis met vier elementen: kathode, anode en twee roosters (stuurrooster en schermrooster)."),
("s21","Wat is een penthode?","Een buis met vijf elementen: kathode, anode en drie roosters (stuurrooster g1, schermrooster g2 en remrooster g3)."),
("s21","Wat doet het schermrooster?","Het krijgt een constante positieve spanning (voor wisselspanning ontkoppeld). Het schermt de capaciteit tussen anode en stuurrooster af en verkleint de invloed van de anodespanning. De inwendige weerstand en dus de mogelijke versterking nemen toe."),
("s21","Welk probleem van de tetrode lost het remrooster op?","Secundaire emissie: elektronen die met hoge snelheid op de anode botsen, maken er andere elektronen uit los. Het remrooster duwt ze terug naar de anode."),
("s21","Waarmee wordt het remrooster van een penthode meestal verbonden?","Met de kathode; het is daardoor negatief ten opzichte van de anode."),
("s21","Waarom moet het schermrooster met een condensator naar 0 V worden ontkoppeld?","Zodat er geen signaalwisselspanning op g2 komt. De afscherming van de anode-stuurroostercapaciteit blijft zo in stand."),
("s21","Hoe splitst de stroom zich in een penthode?","De kathodestroom I_k wordt gesplitst in anodestroom I_a en schermroosterstroom I_g2. I_g2 is veel kleiner dan I_a."),
("s21","Welke roosterbenamingen worden gebruikt in gegevenstabellen?","g1 voor het stuurrooster, g2 voor het schermrooster en g3 voor het remrooster."),
("s24","Hoe is een bipolaire transistor opgebouwd?","Drie lagen halfgeleider: NPN (N-P-N) of PNP. Twee PN-overgangen. De lagen heten emitter, basis en collector."),
("s24","Waarom heet een transistor bipolair en een FET unipolair?","Een bipolaire transistor heeft twee PN-overgangen, een junctie-FET één."),
("s24","Wat is de functie van de emitter, de basis en de collector?","De emitter zendt de ladingdragers uit (de basis in), de basis regelt de stroom en de collector verzamelt de meeste ladingdragers."),
("s24","Hoe werkt een transistor in grote lijnen?","Een kleine basisstroom stuurt een veel grotere collectorstroom. De meeste ladingdragers uit de emitter bereiken de collector voordat ze in de basis recombineren."),
("s24","Waarom is een bipolaire transistor een stroomversterker?","Niet een spanning maar een kleine stroom (basisstroom) stuurt een grote stroom (collectorstroom)."),
("s24","Wat is het verschil in polariteit tussen NPN en PNP?","Tegengesteld: plus bij NPN wordt min bij PNP. Bij PNP zijn de ladingdragers gaten."),
("s24","Welk type transistor is tegenwoordig het meest gebruikt?","De NPN-transistor van silicium. Germanium en PNP komen minder voor."),
("s25","Hoe is de stroomversterking β of h_FE gedefinieerd?","β = h_FE = I_c / I_b (collectorstroom gedeeld door basisstroom)."),
("s25","Waar staat h_FE voor?","F van Forward (voorwaartse stroom), E van Emitter (emitterschakeling)."),
("s25","Tussen welke waarden ligt β ongeveer?","Van ongeveer 5 tot ongeveer 1000, afhankelijk van het type. De werkelijke waarde ligt tussen ruwweg de helft en het dubbele van de opgegeven waarde."),
("s25","Hoe is de emitterstroom te berekenen?","I_e = I_c + I_b = (β + 1) · I_b."),
("s25","Een transistor heeft I_c = 20 mA en I_b = 200 µA. Hoe groot is I_e?","I_e = I_c + I_b = 20,2 mA."),
("s25","Een transistor heeft I_c = 20 mA en I_b = 200 µA. Hoe groot is β?","β = I_c / I_b = 20 mA / 0,2 mA = 100."),
("s25","Hoe groot is de basis-emitterspanning U_be van een geleidende transistor?","Ongeveer 0,6 V voor silicium en ongeveer 0,2 V voor germanium (de drempelspanning van de basis-emitterdiode)."),
("s25","Waarom is bij een transistor met U_be = 0 V geen stroom?","De basis-emitterjunctie is een diode: onder de drempelspanning loopt geen stroom. Een FET of buis geleidt wel bij U = 0."),
("s25","Wat valt op aan de Ic/Uce-karakteristiek van een transistor?","Een zeer steil begin (scherpe knik, Uce kleiner dan 1 V) en daarna een vrijwel vlakke, rechte lijn: hoge inwendige weerstand aan de collector."),
("s25","Is de transistor aan de emitter laag- of hoogohmig, en aan de collector?","Aan de emitter laagohmig, aan de collector hoogohmig. Zo’n transistor versterkt effectief."),
("s26","Waarom moet een transistor worden ingesteld?","Er moet stroom door lopen (U_be boven de drempel) en de collectorspanning moet ongeveer midden tussen minimum en maximum liggen voor een signaal zonder vervorming."),
("s26","Waar moet de collectorspanning zonder signaal ongeveer liggen?","Halverwege tussen de laagste en de hoogste collectorspanning (de voedingsspanning), zodat het signaal ruimte heeft."),
("s26","Wat gebeurt er als de collectorgelijkspanning te hoog of te laag is ingesteld?","Bij een groot signaal ontstaat vervorming (clipping)."),
("s26","Welke twee instelmanieren worden besproken?","Basis via weerstand R_b aan de voedingsspanning, of een spanningsdeler (R1, R2) naar de basis met een emitterweerstand R_e."),
("s26","Formule voor de basisweerstand R_b bij instelling met één weerstand?","R_b = (U_voeding − U_be) / I_b, met I_b = I_c / β en U_be ≈ 0,6 V."),
("s26","Waarom wordt instelling met alleen R_b niet vaak toegepast?","β verschilt per exemplaar en hangt af van de temperatuur. De instelling kan daardoor ‘aan de wandel’ gaan."),
("s26","Waarom voegt men een emitterweerstand toe en gebruikt men een spanningsdeler?","De instelling is stabieler en minder afhankelijk van β. De emitterweerstand houdt de transistor in het gareel."),
("s26","Hoe groot lijkt R_e vanaf de basis gezien?","(β + 1) keer zo groot, dus ongeveer β · R_e. Dat is R_x, die parallel aan R2 staat."),
("s26","Hoe bereken je de basisspanning U_b bij een emitterweerstand?","U_b = U_e + U_be = I_e · R_e + 0,6 V (Si)."),
("s26","Hoe groot is de spanningsversterking van een transistor zonder emitterweerstand?","Au = R_c / (1/S) = R_c · S. Door de grote steilheid van een transistor kan dat zeer hoog zijn (bijvoorbeeld 260)."),
("s26","Hoe groot is de spanningsversterking met emitterweerstand?","Au = R_c / (R_e + 1/S) ≈ R_c / R_e, omdat 1/S bij een transistor heel klein is."),
("s26","Hoe groot is de stroomversterking van de instelschakeling met emitterweerstand?","Gelijk aan β."),
("s27","Welke drie basisschakelingen heeft een transistor?","GES (gemeenschappelijke emitter), GBS (gemeenschappelijke basis) en GCS (gemeenschappelijke collector, emittervolger)."),
("s27","Welke transistorschakeling hoort bij de GSS, GGS en GDS van een FET?","GSS ↔ GES, GGS ↔ GBS, GDS ↔ GCS."),
("s28","Wat zijn ingang en uitgang van de GES?","Ingang: basis. Uitgang: collector. De emitter is gemeenschappelijk."),
("s28","Welke eigenschappen heeft de GES?","Ingangsweerstand matig, uitgangsweerstand hoog, spanningsversterking vrijwel R_c/R_e, stroomversterking zeer groot, vermogensversterking zeer groot, in tegenfase."),
("s28","Is de spanningsversterking van een GES groter of kleiner dan R_c/R_e?","Iets kleiner (bij een transistor heel weinig, bij een FET meer)."),
("s29","Wat zijn ingang en uitgang van de GBS?","Ingang: emitter. Uitgang: collector. De basis is gemeenschappelijk (voor wisselspanning ontkoppeld)."),
("s29","Welke eigenschappen heeft de GBS?","Ingangsweerstand laag, uitgangsweerstand hoog, spanningsversterking vrijwel R_c/R_e, stroomversterking 1, vermogensversterking vrijwel R_c/R_e, in fase."),
("s30","Wat zijn ingang en uitgang van de GCS?","Ingang: basis. Uitgang: emitter. De collector ligt direct aan de voedingsspanning (geen collectorweerstand)."),
("s30","Welke eigenschappen heeft de GCS (emittervolger)?","Ingangsweerstand matig, uitgangsweerstand laag, spanningsversterking 1, stroomversterking zeer groot, vermogensversterking groot, in fase."),
("s30","Waarom is de instelling van een emittervolger minder kritisch dan die van een GES?","Er zijn geen spanningsschommelingen op de collector, want die ligt aan de voedingsspanning."),
("s30","Waarvoor gebruik je een emittervolger?","Om een hoogohmige signaalbron om te zetten naar een laagohmige, praktisch zonder signaalverlies."),
("s30","Waarom is de emittervolger beter dan de sourcevolger qua signaalverlies?","De steilheid van een transistor is veel groter, dus 1/S is verwaarloosbaar klein ten opzichte van R_e."),
("s31","Welke transistorschakeling heeft een lage ingangsweerstand?","De GBS (ingang op de emitter)."),
("s31","Welke transistorschakeling heeft stroomversterking 1?","De GBS."),
("s31","Welke transistorschakelingen hebben in- en uitgang in fase?","GBS en GCS. De GES keert de fase om."),
("s31","Welke transistorschakeling heeft een spanningsversterking van 1?","De GCS (emittervolger)."),
]

